-- Complete source catalogue. Existing v1 profiles/selections/snapshots are never rewritten.
BEGIN;
CREATE TABLE public.air_tariff_catalogues (
 id uuid PRIMARY KEY,parent_id uuid UNIQUE REFERENCES public.air_tariff_catalogues(id),revision integer NOT NULL CHECK(revision>0),
 effective_from date NOT NULL CHECK(effective_from>=DATE '2026-10-16'),effective_to date CHECK(effective_to>=effective_from),
 source_reference text NOT NULL CHECK(length(btrim(source_reference)) BETWEEN 10 AND 2000),payload jsonb NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES auth.users(id)
);
-- The existing append-only selection is the single canonical generation for BOTH families.
-- A v2 selection has profile_id=NULL and exactly one immutable extension, inserted atomically.
CREATE TABLE public.air_tariff_bases (
 selection_id uuid PRIMARY KEY REFERENCES public.air_handling_selections(id),catalogue_id uuid NOT NULL REFERENCES public.air_tariff_catalogues(id),basis jsonb NOT NULL
);
ALTER TABLE public.air_tariff_catalogues ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.air_tariff_bases ENABLE ROW LEVEL SECURITY;
CREATE POLICY air_catalogues_read ON public.air_tariff_catalogues FOR SELECT TO authenticated USING(public.has_workspace_access());
CREATE POLICY air_bases_read ON public.air_tariff_bases FOR SELECT TO authenticated USING(public.has_workspace_access() AND EXISTS(SELECT 1 FROM public.air_handling_selections s WHERE s.id=selection_id));
REVOKE ALL ON public.air_tariff_catalogues,public.air_tariff_bases FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public.air_tariff_catalogues,public.air_tariff_bases TO authenticated,service_role;
CREATE TRIGGER air_catalogue_immutable BEFORE UPDATE OR DELETE ON public.air_tariff_catalogues FOR EACH ROW EXECUTE FUNCTION public.air_handling_immutable();
CREATE TRIGGER air_basis_immutable BEFORE UPDATE OR DELETE ON public.air_tariff_bases FOR EACH ROW EXECUTE FUNCTION public.air_handling_immutable();

CREATE FUNCTION public.air_tariff_payload_valid(p jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$
DECLARE e jsonb;k text;
BEGIN
 IF p->>'schema_version' IS DISTINCT FROM '2' OR p->>'supplier' IS DISTINCT FROM '2AS' OR p->>'airport' IS DISTINCT FROM 'DSS'
  OR jsonb_typeof(p->'entries') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'entries') NOT BETWEEN 1 AND 500 THEN RETURN false;END IF;
 IF (SELECT count(DISTINCT item->>'key') FROM jsonb_array_elements(p->'entries') item)<>jsonb_array_length(p->'entries') THEN RETURN false;END IF;
 FOR e IN SELECT * FROM jsonb_array_elements(p->'entries') LOOP
  IF NOT e ?& ARRAY['key','section','label','code','value','unit','minimum','weight_from_kg','weight_to_kg','day_from','day_to','free_hours','threshold','condition','qualification','source']
   OR jsonb_typeof(e->'key') IS DISTINCT FROM 'string' OR jsonb_typeof(e->'label') IS DISTINCT FROM 'string' OR length(e->>'label') NOT BETWEEN 1 AND 2000
   OR jsonb_typeof(e->'condition') IS DISTINCT FROM 'string' OR length(e->>'condition')>4000
   OR jsonb_typeof(e->'section') IS DISTINCT FROM 'string' OR jsonb_typeof(e->'source') IS DISTINCT FROM 'object'
   OR jsonb_typeof(e->'qualification') IS DISTINCT FROM 'string' OR jsonb_typeof(e->'unit') IS DISTINCT FROM 'string'
   OR (e->'code'<>'null'::jsonb AND jsonb_typeof(e->'code') IS DISTINCT FROM 'string')
   OR e->>'qualification' NOT IN ('documented','ambiguous','missing')
   OR e->>'unit' NOT IN ('XOF','XOF/kg','XOF/kg/jour','%','XOF/heure','XOF/heure commencée/agent','XOF/heure commencée','XOF/m²/mois','XOF/palette','XOF/jour','% achat facture','XOF/mètre','XOF/aller-retour','information') THEN RETURN false;END IF;
  FOR k IN SELECT unnest(ARRAY['value','minimum','weight_from_kg','weight_to_kg','day_from','day_to','free_hours','threshold']) LOOP
   IF e->k<>'null'::jsonb AND (jsonb_typeof(e->k)<>'number' OR (e->>k)::numeric NOT BETWEEN 0 AND 999999999) THEN RETURN false;END IF;
  END LOOP;
 END LOOP;RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END;$$;
ALTER TABLE public.air_tariff_catalogues ADD CONSTRAINT air_catalogue_shape CHECK(public.air_tariff_payload_valid(payload));
CREATE FUNCTION public.air_tariff_basis_valid(p jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$
DECLARE s jsonb:=p->'ordinary_storage';
BEGIN
 RETURN COALESCE(jsonb_typeof(p)='object' AND (p-ARRAY['general_cargo_confirmed','warehouse_bracket_confirmed','ordinary_storage'])='{}'::jsonb
  AND p->'general_cargo_confirmed'='true'::jsonb AND jsonb_typeof(p->'warehouse_bracket_confirmed')='boolean'
  AND jsonb_typeof(s)='object' AND (s-ARRAY['enabled','tariff_key','weight_fact_id','billable_days','days_status','source_reference'])='{}'::jsonb
  AND s ?& ARRAY['enabled','tariff_key','weight_fact_id','billable_days','days_status','source_reference'] AND jsonb_typeof(s->'enabled')='boolean'
  AND s->>'tariff_key' IN ('storage_0','storage_1','storage_2','storage_3')
  AND (s->'weight_fact_id'='null'::jsonb OR (s->>'weight_fact_id')::uuid IS NOT NULL)
  AND (s->'billable_days'='null'::jsonb OR (jsonb_typeof(s->'billable_days')='number' AND (s->>'billable_days')::numeric BETWEEN 0 AND 999999))
  AND s->>'days_status' IN ('confirmed','assumed','unknown') AND jsonb_typeof(s->'source_reference')='string' AND length(s->>'source_reference')<=2000,false);
EXCEPTION WHEN OTHERS THEN RETURN false;
END;$$;
ALTER TABLE public.air_tariff_bases ADD CONSTRAINT air_basis_shape CHECK(public.air_tariff_basis_valid(basis));

ALTER FUNCTION public.air_handling_read(uuid) RENAME TO air_handling_read_legacy;
CREATE FUNCTION public.air_handling_read(p_case_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE r jsonb;
BEGIN
 r:=public.air_handling_read_legacy(p_case_id);
 IF p_case_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.air_tariff_bases WHERE selection_id=(r#>>'{selection,id}')::uuid) THEN
  RAISE EXCEPTION 'AIR catalogue v2 requires current runtime' USING ERRCODE='40001';END IF;
 RETURN r;
END;$$;
REVOKE ALL ON FUNCTION public.air_handling_read(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.air_handling_read(uuid) TO authenticated;
CREATE FUNCTION public.air_tariff_read(p_case_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE old jsonb;ext public.air_tariff_bases;cat public.air_tariff_catalogues;
BEGIN
 old:=public.air_handling_read_legacy(p_case_id); -- Existing admission, portfolio and canonical selection.
 IF p_case_id IS NULL THEN RETURN old||jsonb_build_object('catalogues',COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.revision) FROM public.air_tariff_catalogues c),'[]'::jsonb));END IF;
 SELECT * INTO ext FROM public.air_tariff_bases WHERE selection_id=(old#>>'{selection,id}')::uuid;
 IF ext.selection_id IS NOT NULL THEN SELECT * INTO cat FROM public.air_tariff_catalogues WHERE id=ext.catalogue_id;END IF;
 RETURN old||jsonb_build_object('catalogue',CASE WHEN cat.id IS NULL THEN NULL ELSE to_jsonb(cat) END,'basis',ext.basis);
END;$$;
CREATE FUNCTION public.air_tariff_publish(p_id uuid,p_parent_id uuid,p_payload jsonb,p_effective_from date,p_effective_to date,p_source_reference text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE par public.air_tariff_catalogues;prior public.air_tariff_catalogues;
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_workspace_access() OR NOT public.has_tariff_admin_role() THEN RAISE EXCEPTION 'Tariff administration required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('air_tariff_catalogues',0));
 SELECT * INTO prior FROM public.air_tariff_catalogues WHERE id=p_id;
 IF FOUND THEN
  IF prior.parent_id IS NOT DISTINCT FROM p_parent_id AND prior.payload=p_payload AND prior.effective_from=p_effective_from AND prior.effective_to IS NOT DISTINCT FROM p_effective_to AND prior.source_reference=p_source_reference AND prior.created_by=auth.uid() THEN RETURN p_id;END IF;
  RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='40001';END IF;
 SELECT * INTO par FROM public.air_tariff_catalogues WHERE id=p_parent_id;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.air_tariff_catalogues WHERE parent_id=p_parent_id) THEN RAISE EXCEPTION 'Catalogue revision changed' USING ERRCODE='40001';END IF;
 IF p_effective_from<CURRENT_DATE OR NOT public.air_tariff_payload_valid(p_payload) THEN RAISE EXCEPTION 'Invalid catalogue or retroactive validity';END IF;
 -- Every source entry survives each revision, with exact original provenance. No partial payload drops.
 IF (p_payload-'entries')<>(par.payload-'entries') OR jsonb_array_length(p_payload->'entries')<>jsonb_array_length(par.payload->'entries')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(par.payload->'entries') a WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'entries') b WHERE a->>'key'=b->>'key' AND a->'source'=b->'source' AND a->'section'=b->'section')) THEN RAISE EXCEPTION 'Complete source inventory required';END IF;
 INSERT INTO public.air_tariff_catalogues(id,parent_id,revision,effective_from,effective_to,source_reference,payload,created_by)
 VALUES(p_id,p_parent_id,par.revision+1,p_effective_from,p_effective_to,p_source_reference,p_payload,auth.uid());RETURN p_id;
END;$$;
CREATE FUNCTION public.air_tariff_select(p_id uuid,p_case_id uuid,p_expected_id uuid,p_catalogue_id uuid,p_basis jsonb,p_source_reference text,p_context_hash text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE c public.quote_cases;head public.air_handling_selections;prior public.air_handling_selections;
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_workspace_access() THEN RAISE EXCEPTION 'Workspace admission required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM public.quote_cases WHERE id=p_case_id FOR UPDATE;
 IF NOT FOUND OR NOT public.has_case_write_access(p_case_id) THEN RAISE EXCEPTION 'Case not editable' USING ERRCODE='42501';END IF;
 SELECT * INTO prior FROM public.air_handling_selections WHERE id=p_id;
 IF FOUND THEN
  IF prior.case_id=p_case_id AND prior.context_hash=p_context_hash AND prior.created_by=auth.uid() AND prior.source_reference=p_source_reference AND EXISTS(SELECT 1 FROM public.air_tariff_bases WHERE selection_id=p_id AND catalogue_id=p_catalogue_id AND basis=p_basis) THEN RETURN p_id;END IF;
  RAISE EXCEPTION 'Idempotency conflict' USING ERRCODE='40001';END IF;
 IF c.status::text NOT IN ('INTAKE','FACTS_PARTIAL','NEED_INFO','READY_TO_PRICE','DECISIONS_PENDING','DECISIONS_COMPLETE','ACK_READY_FOR_PRICING','PRICED_DRAFT','QUOTED_VERSIONED') THEN RAISE EXCEPTION 'Case not editable';END IF;
 IF c.request_type::text !~ '^AIR_IMPORT(_|$)' OR (SELECT count(*) FROM public.quote_request_lines WHERE case_id=p_case_id)>=2 THEN RAISE EXCEPTION 'AIR import mono-lot only';END IF;
 SELECT * INTO head FROM public.air_handling_selections WHERE case_id=p_case_id ORDER BY version DESC LIMIT 1;
 IF head.id IS DISTINCT FROM p_expected_id OR public.air_handling_context_hash(p_case_id) IS DISTINCT FROM p_context_hash THEN RAISE EXCEPTION 'Case generation or context changed' USING ERRCODE='40001';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.air_tariff_catalogues WHERE id=p_catalogue_id AND effective_from<=CURRENT_DATE AND (effective_to IS NULL OR effective_to>=CURRENT_DATE)) OR NOT public.air_tariff_basis_valid(p_basis) THEN RAISE EXCEPTION 'Catalogue or basis invalid';END IF;
 INSERT INTO public.air_handling_selections(id,case_id,version,profile_id,source_reference,warehouse_bracket_confirmed,context_hash,created_by)
 VALUES(p_id,p_case_id,COALESCE(head.version,0)+1,NULL,p_source_reference,(p_basis->>'warehouse_bracket_confirmed')::boolean,p_context_hash,auth.uid());
 INSERT INTO public.air_tariff_bases(selection_id,catalogue_id,basis) VALUES(p_id,p_catalogue_id,p_basis);RETURN p_id;
END;$$;

CREATE FUNCTION public.air_tariff_assert_result(p_case_id uuid,p_selection_id uuid,p_context_hash text,p_lines jsonb,p_inputs jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE head public.air_handling_selections;ext public.air_tariff_bases;cat public.air_tariff_catalogues;e jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.quote_cases WHERE id=p_case_id FOR UPDATE;
 PERFORM 1 FROM public.quote_facts WHERE case_id=p_case_id ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.quote_request_lines WHERE case_id=p_case_id ORDER BY id FOR SHARE;
 SELECT * INTO head FROM public.air_handling_selections WHERE case_id=p_case_id ORDER BY version DESC LIMIT 1;
 SELECT * INTO ext FROM public.air_tariff_bases WHERE selection_id=head.id;
 SELECT * INTO cat FROM public.air_tariff_catalogues WHERE id=ext.catalogue_id;
 IF ext.selection_id IS NULL OR head.id IS DISTINCT FROM p_selection_id OR head.context_hash IS DISTINCT FROM p_context_hash OR public.air_handling_context_hash(p_case_id) IS DISTINCT FROM p_context_hash THEN RAISE EXCEPTION 'Handling generation or context changed' USING ERRCODE='40001';END IF;
 IF jsonb_typeof(p_lines) IS DISTINCT FROM 'array' OR (SELECT count(*) FROM jsonb_array_elements(p_lines) l WHERE l#>'{source,air_handling}' IS NOT NULL)<>1 THEN RAISE EXCEPTION 'Handling evidence missing';END IF;
 SELECT l#>'{source,air_handling}' INTO e FROM jsonb_array_elements(p_lines) l WHERE l#>'{source,air_handling}' IS NOT NULL;
 IF e->>'schema_version' IS DISTINCT FROM '2' OR e->>'selection_id' IS DISTINCT FROM head.id::text OR e->>'context_hash' IS DISTINCT FROM p_context_hash
  OR e->'catalogue' IS DISTINCT FROM to_jsonb(cat) OR e->'basis' IS DISTINCT FROM ext.basis OR p_inputs->'airHandling' IS DISTINCT FROM e
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_lines) l WHERE l#>'{source,air_handling}' IS NOT NULL AND (l#>>'{source,type}' IS DISTINCT FROM 'TO_CONFIRM' OR l->'amount' IS DISTINCT FROM 'null'::jsonb)) THEN RAISE EXCEPTION 'Handling catalogue or basis evidence differs';END IF;
END;$$;
CREATE FUNCTION public.air_tariff_result_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s uuid;
BEGIN
 -- Blocks old workers that never read v2, including a request type changed during the run.
 IF NEW.status::text='success' THEN
  PERFORM 1 FROM public.quote_cases WHERE id=NEW.case_id FOR UPDATE;
  SELECT id INTO s FROM public.air_handling_selections WHERE case_id=NEW.case_id ORDER BY version DESC LIMIT 1;
  IF EXISTS(SELECT 1 FROM public.air_tariff_bases WHERE selection_id=s) OR NEW.inputs_json#>>'{airHandling,schema_version}'='2' THEN
   PERFORM public.air_tariff_assert_result(NEW.case_id,(NEW.inputs_json#>>'{airHandling,selection_id}')::uuid,NEW.inputs_json#>>'{airHandling,context_hash}',NEW.tariff_lines,NEW.inputs_json);
  END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER air_tariff_run_guard BEFORE INSERT OR UPDATE ON public.pricing_runs FOR EACH ROW EXECUTE FUNCTION public.air_tariff_result_guard();
CREATE FUNCTION public.air_tariff_finish(p_run_id uuid,p_case_id uuid,p_selection_id uuid,p_context_hash text,p_result jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE affected integer;inputs jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.quote_cases WHERE id=p_case_id FOR UPDATE;
 SELECT inputs_json INTO inputs FROM public.pricing_runs WHERE id=p_run_id AND case_id=p_case_id AND status='running' FOR UPDATE;
 IF NOT FOUND OR p_result->>'status' IS DISTINCT FROM 'success' THEN RAISE EXCEPTION 'Pricing run changed';END IF;
 PERFORM public.air_tariff_assert_result(p_case_id,p_selection_id,p_context_hash,p_result->'tariff_lines',inputs);
 UPDATE public.pricing_runs SET status='success',engine_request=p_result->'engine_request',engine_response=p_result->'engine_response',outputs_json=p_result->'outputs_json',tariff_lines=p_result->'tariff_lines',
 total_ht=(p_result->>'total_ht')::numeric,total_ttc=(p_result->>'total_ttc')::numeric,currency=p_result->>'currency',tariff_sources=p_result->'tariff_sources',completed_at=(p_result->>'completed_at')::timestamptz,duration_ms=(p_result->>'duration_ms')::integer
 WHERE id=p_run_id AND case_id=p_case_id AND status='running';GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected<>1 THEN RAISE EXCEPTION 'Pricing run changed';END IF;
END;$$;
REVOKE ALL ON FUNCTION public.air_tariff_payload_valid(jsonb),public.air_tariff_basis_valid(jsonb),public.air_tariff_result_guard(),public.air_tariff_assert_result(uuid,uuid,text,jsonb,jsonb),public.air_tariff_finish(uuid,uuid,uuid,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.air_tariff_payload_valid(jsonb),public.air_tariff_basis_valid(jsonb) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.air_tariff_finish(uuid,uuid,uuid,text,jsonb) TO service_role;
REVOKE ALL ON FUNCTION public.air_tariff_read(uuid),public.air_tariff_publish(uuid,uuid,jsonb,date,date,text),public.air_tariff_select(uuid,uuid,uuid,uuid,jsonb,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.air_tariff_read(uuid),public.air_tariff_publish(uuid,uuid,jsonb,date,date,text),public.air_tariff_select(uuid,uuid,uuid,uuid,jsonb,text,text) TO authenticated;
